ALTER TABLE client DROP INDEX IF EXISTS client_business_id_email_unique, DROP INDEX IF EXISTS client_email, DROP INDEX IF EXISTS client_phone, DROP COLUMN IF EXISTS `name`, DROP COLUMN IF EXISTS lastname, DROP COLUMN IF EXISTS phone, DROP COLUMN IF EXISTS email, DROP COLUMN IF EXISTS description, MODIFY COLUMN IF EXISTS name_encrypted VARBINARY(2080) NOT NULL, MODIFY COLUMN IF EXISTS lastname_encrypted VARBINARY(2080) NOT NULL;
ALTER TABLE employee DROP INDEX IF EXISTS employee_phone, DROP INDEX IF EXISTS employee_email, DROP COLUMN IF EXISTS `name`, DROP COLUMN IF EXISTS lastname, DROP COLUMN IF EXISTS phone, DROP COLUMN IF EXISTS email, MODIFY COLUMN IF EXISTS name_encrypted VARBINARY(2080) NOT NULL, MODIFY COLUMN IF EXISTS lastname_encrypted VARBINARY(2080) NOT NULL;
